import{_ as t,H as a,f as p,i as n}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"26 | 关于DataAgent的非共识：噱头、降低门槛、提效工具还是颠覆传统？","description":"","frontmatter":{},"headers":[{"level":2,"title":"数据驱动面临的鸿沟","slug":"数据驱动面临的鸿沟","link":"#数据驱动面临的鸿沟","children":[]},{"level":2,"title":"对 Data Agent 的三种定位","slug":"对-data-agent-的三种定位","link":"#对-data-agent-的三种定位","children":[{"level":3,"title":"观点一：噱头论","slug":"观点一-噱头论","link":"#观点一-噱头论","children":[]},{"level":3,"title":"观点二：降低门槛论","slug":"观点二-降低门槛论","link":"#观点二-降低门槛论","children":[]},{"level":3,"title":"观点三：提效工具论","slug":"观点三-提效工具论","link":"#观点三-提效工具论","children":[]},{"level":3,"title":"三种观点的共同局限","slug":"三种观点的共同局限","link":"#三种观点的共同局限","children":[]}]},{"level":2,"title":"从知识库开始构建 Data Agent","slug":"从知识库开始构建-data-agent","link":"#从知识库开始构建-data-agent","children":[{"level":3,"title":"知识库是核心基础","slug":"知识库是核心基础","link":"#知识库是核心基础","children":[]},{"level":3,"title":"从知识库到 Agent","slug":"从知识库到-agent","link":"#从知识库到-agent","children":[]}]},{"level":2,"title":"关键实践心得","slug":"关键实践心得","link":"#关键实践心得","children":[{"level":3,"title":"心得一：大模型能力是前提","slug":"心得一-大模型能力是前提","link":"#心得一-大模型能力是前提","children":[]},{"level":3,"title":"心得二：指标口径加数据语义是准确率关键","slug":"心得二-指标口径加数据语义是准确率关键","link":"#心得二-指标口径加数据语义是准确率关键","children":[]},{"level":3,"title":"心得三：Workflow Agent 还是 Agentic Agent","slug":"心得三-workflow-agent-还是-agentic-agent","link":"#心得三-workflow-agent-还是-agentic-agent","children":[]},{"level":3,"title":"心得四，GUI 加 Chatbox 的结合","slug":"心得四-gui-加-chatbox-的结合","link":"#心得四-gui-加-chatbox-的结合","children":[]}]},{"level":2,"title":"实践案例：一个银行业的月度运营管理流程","slug":"实践案例-一个银行业的月度运营管理流程","link":"#实践案例-一个银行业的月度运营管理流程","children":[{"level":3,"title":"完整流程介绍","slug":"完整流程介绍","link":"#完整流程介绍","children":[]},{"level":3,"title":"关键认知和体会","slug":"关键认知和体会","link":"#关键认知和体会","children":[]}]},{"level":2,"title":"Data Agent 带来的变革可能性","slug":"data-agent-带来的变革可能性","link":"#data-agent-带来的变革可能性","children":[]},{"level":2,"title":"课程总结","slug":"课程总结","link":"#课程总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大数据应用实战/26｜关于DataAgent的非共识：噱头、降低门槛、提效工具还是颠覆传统？.md","filePath":"大数据应用实战/26｜关于DataAgent的非共识：噱头、降低门槛、提效工具还是颠覆传统？.md","lastUpdated":1795555553000}'),l={name:"大数据应用实战/26｜关于DataAgent的非共识：噱头、降低门槛、提效工具还是颠覆传统？.md"};function i(g,e,A,r,o,h){return a(),p("div",null,[...e[0]||(e[0]=[n('<h1 id="_26-关于dataagent的非共识-噱头、降低门槛、提效工具还是颠覆传统" tabindex="-1">26 | 关于DataAgent的非共识：噱头、降低门槛、提效工具还是颠覆传统？ <a class="header-anchor" href="#_26-关于dataagent的非共识-噱头、降低门槛、提效工具还是颠覆传统" aria-label="Permalink to &quot;26 | 关于DataAgent的非共识：噱头、降低门槛、提效工具还是颠覆传统？&quot;">​</a></h1><p>你好，我是曹犟。</p><p>在上节课中，我们讨论了大模型如何赋能非结构化数据处理，今天这节课，我们继续探讨大模型对大数据行业的影响，聊一聊 Data Agent 这个热门话题。</p><h2 id="数据驱动面临的鸿沟" tabindex="-1">数据驱动面临的鸿沟 <a class="header-anchor" href="#数据驱动面临的鸿沟" aria-label="Permalink to &quot;数据驱动面临的鸿沟&quot;">​</a></h2><p>在讨论 Data Agent 之前，我们先来看看企业在实现数据驱动时面临的挑战。</p><p>在过去十年服务 2000 多家客户的过程中，我发现企业要真正实现数据驱动，至少面临四大鸿沟。</p><ul><li><p>技术鸿沟：搭建和维护一个大数据系统的技术门槛很高。需要懂数据采集、数据仓库、OLAP 数据库、BI 工具，还要懂数据治理、数据质量管理。很多企业缺少这样的人才，即使搭建起来了，后续的运维成本也很高。</p></li><li><p>数据鸿沟：有了系统，还要有高质量的数据。数据治理是一个长期的工程，需要定义元数据、建立数据模型、保证数据质量、梳理数据血缘。更重要的是，数据要和业务场景匹配。很多企业采集了大量数据，但不知道如何用这些数据解决实际的业务问题。</p></li><li><p>业务落地鸿沟：从目标拆解到策略执行再到效果归因，需要形成完整的闭环。这不仅需要懂业务、懂数据，还要懂运营。很多企业看到了数据洞察，但不知道如何转化为具体的业务行动，或者执行了策略，却无法准确归因效果。</p></li><li><p>管理挑战：数据驱动需要跨部门协作，涉及技术部门、业务部门、数据部门之间的利益协调。很多时候，技术上都准备好了，但组织协调跟不上，数据就无法发挥价值。</p></li></ul><p>这四大鸿沟，导致了一个现实问题，那就是再好的工具，用不好也没有价值。</p><p>而为了让客户用好工具，有了“陪跑”这种模式。对于内部产品，数据团队会配置数据 BP，专门辅导业务部门用好数据工具。对于商业产品，则会提供代运营服务，帮助客户制定策略、执行落地。</p><p>陪跑模式确实有价值，它能帮助客户跨越这些鸿沟，真正用好数据工具。但是，这种模式也有明显的局限。</p><ul><li><p>不可持续：陪跑依赖重人力投入，很难规模化。一个数据 BP 能服务的业务部门是有限的，一个代运营团队能服务的客户也是有限的。业务增长了，就需要投入更多人力，成本会线性增长。</p></li><li><p>知识沉淀困难：陪跑过程中，专家积累的经验和知识，很难传承和复用。每次服务新客户，都要从头开始，效果也难以稳定。客户的成功经验也很难直接复制。</p></li></ul><p>那么，有没有可能将这些专家经验产品化，让知识可以沉淀、可以复用、可以规模化呢？这就是我们思考 Data Agent 的出发点。</p><h2 id="对-data-agent-的三种定位" tabindex="-1">对 Data Agent 的三种定位 <a class="header-anchor" href="#对-data-agent-的三种定位" aria-label="Permalink to &quot;对 Data Agent 的三种定位&quot;">​</a></h2><p>关于 Data Agent 是什么，业界有不同的观点，我总结为如下三种。</p><h3 id="观点一-噱头论" tabindex="-1">观点一：噱头论 <a class="header-anchor" href="#观点一-噱头论" aria-label="Permalink to &quot;观点一：噱头论&quot;">​</a></h3><p>第一种观点认为，Data Agent 只是大模型热潮下的营销概念，本质上就是 Text-to-SQL，也就是用自然语言查询数据。</p><p>这种观点的理由是，Text-to-SQL 技术早就有了，只不过以前效果不好。现在大模型来了，Text-to-SQL 的准确率提升了，但本质没变，还是把自然语言翻译成 SQL 而已。</p><p>对比传统的 BI 加 SQL 能力，他们认为真实的价值增量很有限。会写 SQL 的人，直接写 SQL更快更准确。不会写 SQL 的人，用自然语言描述需求，还是容易产生歧义，结果也不一定对。</p><p>这种观点有一定的合理性。确实，市面上很多所谓的 Data Agent 产品，核心就是 Text-to-SQL，功能单一，用户体验也不够好。</p><p>但是，这种观点的局限在于，它把 Data Agent 简化为了一个单点的技术能力。如果只能执行一次查询，而不能理解用户意图、多轮对话澄清、调用多种工具、给出洞察建议，那确实只是换了个包装的查询工具而已。</p><h3 id="观点二-降低门槛论" tabindex="-1">观点二：降低门槛论 <a class="header-anchor" href="#观点二-降低门槛论" aria-label="Permalink to &quot;观点二：降低门槛论&quot;">​</a></h3><p>第二种观点认为，Data Agent 的核心价值是降低使用门槛，让业务人员也能分析数据，让需要数据的人直接获取数据。</p><p>这种观点的理由是，传统的数据分析，需要懂 SQL，懂数据模型，懂 BI 工具，门槛很高。而Data Agent 通过对话式交互，业务人员只需要用自然语言提问，就能得到答案，大大降低了使用复杂度。</p><p>比如，运营人员想知道“上周新增用户中，有多少来自北京，他们的 7 日留存情况如何”，直接问 Agent 就可以，不需要找数据分析师帮忙跑数据。</p><p>这种定位的价值是明显的，确实能提升数据的普惠性，让更多人用上数据。</p><p>但是，这种观点的局限在于，它只关注了“用数据的人”这一端，忽略了数据价值发挥的全链路。降低使用门槛，让业务人员能查询数据，只是第一步。但查到数据之后呢？业务人员能否正确理解数据？能否基于数据做出正确的决策？能否将洞察转化为具体的行动？这些问题，单靠降低使用门槛是解决不了的。</p><h3 id="观点三-提效工具论" tabindex="-1">观点三：提效工具论 <a class="header-anchor" href="#观点三-提效工具论" aria-label="Permalink to &quot;观点三：提效工具论&quot;">​</a></h3><p>第三种观点认为，Data Agent 的核心价值是为专业人员提速，自动化重复性工作。</p><p>这种观点的理由是，数据分析师每天要做很多重复性工作。比如，每周生成经营分析周报，每月生成营销效果月报，发现指标异动后做归因分析等。这些工作流程相对固定，但很耗时间。如果能用 Agent 自动化，就能把分析师的时间解放出来，去做更有价值的工作。</p><p>典型的场景包括，周报、月报自动生成。Agent 自动抓取核心指标，生成报告初稿，分析师只需要审核和补充。指标异动自动归因。Agent 发现某个指标异常，自动进行多维度归因分析，找出可能的原因，分析师只需要验证和深挖。</p><p>这种定位的应用边界比较清晰，适合那些流程相对标准化、可以自动化的场景。</p><p>但是，它的局限在于，聚焦在提效，却没有看到更深层的价值，比如知识的积累和复用、从洞察到行动的完整链路。</p><h3 id="三种观点的共同局限" tabindex="-1">三种观点的共同局限 <a class="header-anchor" href="#三种观点的共同局限" aria-label="Permalink to &quot;三种观点的共同局限&quot;">​</a></h3><p>这三种观点，虽然角度不同，但都存在一个根本性的认知局限：它们都将 Data Agent 视为“工具”而非“智能体”。</p><p>工具和智能体的区别在哪里？</p><p>工具是被动的，由人来操作，人定义每一步做什么。而智能体是主动的，能够理解目标、制定计划、调用工具、执行任务、反馈优化。</p><p>噱头论把 Agent 看成 Text-to-SQL 工具，降低门槛论把 Agent 看成查询工具，提效工具论把Agent 看成自动化工具。它们的共同点是，都没有看到 Agent 作为智能体的核心能力：多轮理解意图、自主调用多种工具、给出洞察和建议、形成从分析到行动的完整链路。</p><p>更重要的是，这三种观点都忽略了知识驱动的本质。Data Agent 的核心，不只是大模型的通用能力，而是基于知识库的专业能力。没有知识库，Agent 只能做一些通用的、浅层的分析。有了知识库，Agent 才能做深度的、专业的、场景化的应用。</p><p>同时，这三种观点也未能看到商业模式变革的可能性，这部分我们在第 27 课展开讨论。</p><p>简单来说，Data Agent 最大的价值，不是替代某个工具，而是将专家的知识产品化，从而改变服务的方式和商业模式。</p><h2 id="从知识库开始构建-data-agent" tabindex="-1">从知识库开始构建 Data Agent <a class="header-anchor" href="#从知识库开始构建-data-agent" aria-label="Permalink to &quot;从知识库开始构建 Data Agent&quot;">​</a></h2><p>既然知识是 Data Agent 的核心，那么我们就从知识库开始，来看看如何构建 Data Agent。</p><h3 id="知识库是核心基础" tabindex="-1">知识库是核心基础 <a class="header-anchor" href="#知识库是核心基础" aria-label="Permalink to &quot;知识库是核心基础&quot;">​</a></h3><p>我们试图构建的知识库，不是一个简单的文档库或 FAQ 库，而是一个业务目标驱动的知识视图。这个知识视图包含一个完整的闭环：目标拆解、策略制定、结果归因、知识迭代。</p><p>具体来说，知识库中包含以下几类知识。</p><ul><li><p>管理实践知识：如何进行 OKR 或 KPI 拆解？如何将一个抽象的业务目标，拆解成可执行、可衡量的子目标？这些管理方法论，需要沉淀到知识库中。</p></li><li><p>运营策略库：针对不同的业务场景，有哪些成熟的运营策略？比如，用户分群策略、用户生命周期管理、用户路径优化等。这些策略不是凭空想象，而是在实践中验证过的最佳实践。</p></li><li><p>分析与归因知识：如何进行归因分析？如何定义辅助指标？什么情况下用什么归因模型？这些分析方法，也需要固化到知识库中。</p></li><li><p>用户偏好知识：不同类型的用户，有什么样的偏好？比如，渠道偏好、时间偏好、内容偏好、权益偏好等。这些偏好数据中既有通用规律，也有行业特征，还有企业个性。</p></li></ul><p>这些知识，不是静态的，而是在不断迭代的。每一次策略执行，都会产生新的数据。这些数据经过分析，会产生新的洞察。新的洞察，又会更新知识库中的策略和方法。这样就形成了一个知识迭代的闭环。</p><p>为了支撑这样的知识视图，我们设计了一个五层的知识库架构，简称 SKB（SemanticKnowledge Base）。这五层架构，从下到上，抽象程度逐渐提高，业务含义越来越丰富。</p><p>如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/1.jpeg" alt=""></a></p><ul><li>知识库五层架构</li></ul><p>第一层：数据层。这是最底层，也就是数据仓库或数据湖，按业务域进行治理。比如，用户域、商品域、订单域、营销域等。这一层存储的是原始数据和经过 ETL 处理的明细数据。</p><p>第二层：语义层。这是一个虚拟层，定义了表与表之间的关联关系，以及字段的业务含义。比如，用户表和订单表如何关联？订单金额字段的口径是什么？是否包含退款？是否包含优惠？</p><p>这些语义，都定义在这一层。</p><p>第三层：指标层。这一层固化了核心业务指标的定义和计算逻辑。比如，活跃用户数如何定义？是过去 7 天有登录行为的用户，还是有任意行为的用户？新增用户数如何定义？是按注册时间，还是按首次访问时间？这些指标的口径，必须在企业内部达成共识，并固化下来。</p><p>第四层：MCP 层。这一层封装了语义层和指标层，提供标准的 MCP 接口。通过 MCP，Agent 可以标准化地访问语义层和指标层，而不需要直接操作底层数据库。</p><p>第五层：Agent 层。这是最上层，预定义了场景化的数据处理逻辑。比如，指标异动分析的Agent、经营报告生成的 Agent、运营策略设计的 Agent 等。这些 Agent，封装了特定场景的业务逻辑和分析方法。</p><p>有了这样的分层架构，Agent 在处理任务时，不是直接操作原始数据，而是通过 MCP 访问语义层和指标层，使用统一的业务语言，避免了理解偏差，也保证了分析的准确性。</p><p>除了架构的分层，知识本身也可以分层。我们把知识分为五个层级，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/2.png" alt=""></a></p><ul><li>知识本身可以分为五个层级</li></ul><p>第一层：工具使用知识。这是最底层的知识，也就是如何使用各种工具。比如，如何调用某个API，如何使用某个函数，如何读取某个数据源。这类知识的行业通用性是最强的，但专业性最弱。</p><p>第二层：跨行业通用知识。比如，AARRR 模型、北极星指标、RFM 模型等。这些是数据分析和运营领域的通用方法论，适用于各个行业。</p><p>第三层：行业级通用知识。比如，零售行业的 GMV 计算方法、金融行业的风控指标、教育行业的完课率定义等。这些知识在特定行业内通用，但跨行业可能不适用。</p><p>第四层：行业场景级知识。比如，银行业的“开门红”营销场景、电商的“618”“双十一”促销场景、保险业的“续保提醒”场景等。这些知识更加具体，针对特定场景的增长思路和运营打法。</p><p>第五层：企业级专属知识。比如，某个企业内部定义的用户分群、某个企业的产品体系、某个企业的组织架构等。这些知识是企业独有的，具有最强的专业性。</p><p>在这五个层级中，越往上，知识越专业，价值密度越高，但通用性越低。越往下，知识越通用，但价值密度越低。</p><p>对于 Data Agent 来说，要真正产生价值，必须能够调用上层的专业知识。如果只有底层的通用知识，Agent 的能力就很有限，只能做一些浅层的、通用的分析，很难解决具体的业务问题。</p><h3 id="从知识库到-agent" tabindex="-1">从知识库到 Agent <a class="header-anchor" href="#从知识库到-agent" aria-label="Permalink to &quot;从知识库到 Agent&quot;">​</a></h3><p>有了知识库，下一步就是构建 Agent，不同的应用场景需要不同的 Agent。</p><p>在神策的实践中，我们主要构建了两类 Agent，AI 智能分析师和 AI 智能运营师。</p><p>AI 智能分析师</p><p>AI 智能分析师的定位，是数据分析师的得力助手，而不是替代者。</p><p>它的核心能力包括三个方面。</p><p>第一，精准理解用户问题。通过多轮对话澄清，Agent 能够准确理解用户的真实意图。比如，用户问“销售额下降了”，Agent 会追问“您指的是哪个时间段？是总销售额还是某个品类？是环比还是同比？”通过多轮对话，把模糊的问题变成明确的查询。</p><p>第二，深度理解数据并调用工具。基于语义层和指标层，Agent 知道每个指标的定义、每个字段的含义、表与表之间的关系。它可以自动生成正确的 SQL，调用正确的 API，获取准确的数据。</p><p>第三，初步解读数据并给出建议。Agent 不只是返回数字，还会对数据进行初步的解读。比如，同比下降 15%，在行业中属于什么水平？可能的原因有哪些？建议做什么样的深入分析？这有点类似于从简单的 Chatbox 进化到 Deep Research。不再局限于已知数据的分析，还会主动综合知识库与检索信息来解读数据。</p><p>这个 Agent 的典型场景包括：</p><ul><li><p>指标异动分析：发现某个核心指标异动后，Agent 自动进行多维度归因，从时间、地域、渠道、用户群等多个维度拆解，找出异动的主要原因。</p></li><li><p>经营分析报告：Agent 自动抓取核心指标，计算同比环比，生成可视化图表，输出报告文本。分析师只需要审核和补充，效率大幅提升。</p></li></ul><p>AI 智能运营师</p><p>AI 智能运营师的定位，是从洞察到执行的桥梁。</p><p>它采用多 Agent 协作架构，包含以下几个专门的 Agent：</p><ul><li><p>策略设计 Agent：负责初步策略构思。基于业务目标和数据洞察，生成初步的运营策略方案。</p></li><li><p>策略优化 Agent：负责迭代调整策略。根据反馈和数据，不断优化策略的参数和逻辑。</p></li><li><p>策略创建 Agent：负责翻译为可执行的流程画布。将抽象的策略，转化为具体的自动化流程，包括触发条件、执行动作、分支逻辑等。</p></li><li><p>策略预测 Agent：负责预估策略效果。基于历史数据和模型，预测策略上线后的效果，包括触达人数、预期转化率、预期 ROI 等。</p></li><li><p>策略洞察检索 Agent：负责从知识库检索相关知识。根据当前的场景和目标，检索行业最佳实践、类似案例、相关策略等。</p></li></ul><p>这些 Agent 协同工作，形成一个完整的策略设计和执行链路，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/3.png" alt=""></a></p><ul><li>Agent协同的执行链路示意图</li></ul><p>它的核心价值有两个：</p><ul><li><p>自动创建复杂运营画布，降低使用门槛。传统的营销自动化系统，需要运营人员手动设计复杂的流程画布，门槛很高。而 AI 智能运营师，可以根据业务目标，自动生成流程画布，运营人员只需要审核和调整。</p></li><li><p>提供行业最佳实践，而非盲目摸索。Agent 可以从知识库中检索相关的策略模板和成功案例，帮助运营人员快速找到有效的策略，而不是从零开始摸索。</p></li></ul><h2 id="关键实践心得" tabindex="-1">关键实践心得 <a class="header-anchor" href="#关键实践心得" aria-label="Permalink to &quot;关键实践心得&quot;">​</a></h2><p>在构建 Agent 的过程中，我们积累了一些关键的实践心得，这里分享给大家。</p><h3 id="心得一-大模型能力是前提" tabindex="-1">心得一：大模型能力是前提 <a class="header-anchor" href="#心得一-大模型能力是前提" aria-label="Permalink to &quot;心得一：大模型能力是前提&quot;">​</a></h3><p>顶尖 LLM，如 Claude，在上下文理解和指令遵循上有质的飞跃。</p><p>在我们的实践中，使用 GPT-4.5 及以上能力水平的大模型，One-shot/Few-shot 即可生成准确的 API 调用或 SQL。过去需要反复修正、多轮调试的场景，现在几乎一次性正确。</p><p>这是构建可靠 Agent 的关键前提。如果大模型的能力不够，即使有再完善的知识库，Agent 也很难准确理解用户意图、正确调用工具、给出合理建议。</p><p>所以，选择顶尖的大模型，是第一位的。</p><h3 id="心得二-指标口径加数据语义是准确率关键" tabindex="-1">心得二：指标口径加数据语义是准确率关键 <a class="header-anchor" href="#心得二-指标口径加数据语义是准确率关键" aria-label="Permalink to &quot;心得二：指标口径加数据语义是准确率关键&quot;">​</a></h3><p>AI 必须理解数据语义，也就是每个字段的具体业务含义，也必须遵循指标口径，也就是每个企业对指标的定义。</p><p>我们的指标平台和语义层，就是把这些知识前置，让 AI 在生成查询之前，就知道每个指标的准确定义、每个字段的精确含义。</p><p>这样，就避免了“正确的废话”和“危险的错误”。“正确的废话”是指，查询执行成功了，数字也返回了，但因为理解偏差，数字是错的。“危险的错误”是指，用户相信了错误的数字，并基于此做出了错误的决策。</p><p>准确率，是 Data Agent 的生命线。如果不准确，再方便也没有价值。</p><h3 id="心得三-workflow-agent-还是-agentic-agent" tabindex="-1">心得三：Workflow Agent 还是 Agentic Agent <a class="header-anchor" href="#心得三-workflow-agent-还是-agentic-agent" aria-label="Permalink to &quot;心得三：Workflow Agent 还是 Agentic Agent&quot;">​</a></h3><p>在技术实现上，构建 Agent 有两种主要方式，Workflow Agent 和 Agentic Agent。</p><p>Workflow Agent，也就是基于工作流的 Agent，如基于 coze、Dify 等搭建。通过定义状态机和节点，明确 Agent 的每一步做什么、条件判断的逻辑、工具的调用顺序等。</p><p>它的优势是灵活，状态机和节点清晰，便于嵌入语义层、RAG 和工具编排。开发者可以精确控制 Agent 的行为，针对特定场景进行深度优化。</p><p>它适用的场景包括，复杂业务编排、强流程合规、需要细粒度状态控制的场景。</p><p>它的劣势是开发复杂度高，每个节点、每个分支都需要明确定义，对开发者的要求比较高。</p><p>Agentic Agent，也就是基于 LLM 自主决策的 Agent。通过 Prompt 定义 Agent 的目标和可用工具，由 LLM 自主决定每一步做什么、调用哪个工具。</p><p>它的优势是开箱即用，内置了上下文压缩、工具权限、会话管理等能力，开发者只需要定义好Prompt 和工具接口，就可以快速上线。并且，显然，具有更好的可扩展性，很多时候能交付超过设计者预先设想的结果。</p><p>它适用的场景包括，快速落地、强工具与权限治理、主要依赖 LLM 能力的场景。</p><p>它的劣势则是对于一些复杂的业务逻辑，可能需要在 Prompt 中进行复杂的描述，不如Workflow 清晰直观。</p><p>在神策的实践中，我们在同一类场景中同时使用了两种方式，还没有定论哪种方式是绝对最优解。也许随着模型能力的进一步提升，Agentic Agent 会最终统一所有场景。</p><h3 id="心得四-gui-加-chatbox-的结合" tabindex="-1">心得四，GUI 加 Chatbox 的结合 <a class="header-anchor" href="#心得四-gui-加-chatbox-的结合" aria-label="Permalink to &quot;心得四，GUI 加 Chatbox 的结合&quot;">​</a></h3><p>在产品交互设计上，我们也有一个重要的心得，那就是当前 AI Native 产品不应该是纯对话式交互，而应该是 GUI 加 Chatbox 的结合。我们曾经设想 AI Native 应该“一气呵成”，用户通过纯对话的方式，完成所有操作。</p><p>但实际上线后，用户的反馈出乎意料。</p><p>首先，用户对可控性非常关注。AI 执行的每一步，用户都希望能够点击确认，而不是 AI 自动执行完。比如，AI 建议发送一条营销短信给 1000 个用户，用户希望先看到这 1000 个用户的名单，确认没问题后，再点击发送，而不是 AI 直接发送。</p><p>其次，用户对传统界面有偏好。对于一些标准化的操作，比如信息列表的 CRUD，用户更希望使用传统的 GUI，而不是通过对话来操作。用对话方式来删除一个条目，反而觉得不方便。</p><p>基于这些反馈，我们调整了产品设计，将 AI 对话和传统 GUI 结合起来。对于探索性的分析、策略的设计，使用 Chatbox。对于标准化的操作、信息的管理，使用 GUI。</p><p>这个实践给我们的启发是，在当前技术条件下，AI Native 的理想产品形态，可能不是完全抛弃传统界面，而是让 AI 和传统界面优势互补。Chatbox 负责处理灵活的、探索性的任务，GUI 则处理标准化的、重复性的任务。</p><h2 id="实践案例-一个银行业的月度运营管理流程" tabindex="-1">实践案例：一个银行业的月度运营管理流程 <a class="header-anchor" href="#实践案例-一个银行业的月度运营管理流程" aria-label="Permalink to &quot;实践案例：一个银行业的月度运营管理流程&quot;">​</a></h2><p>为了让大家更直观地理解 Data Agent 的价值，我通过一个银行业完整的月度运营管理流程，来展示分析 Agent 和运营 Agent 如何协同工作，以及知识库在不同层级的调用。</p><h3 id="完整流程介绍" tabindex="-1">完整流程介绍 <a class="header-anchor" href="#完整流程介绍" aria-label="Permalink to &quot;完整流程介绍&quot;">​</a></h3><p>这个月度运营管理流程如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/26/4.png" alt=""></a></p><ul><li>运营管理流程示意图</li></ul><p>第一步：智能月报生成</p><p>由分析 Agent 自动抓取核心指标，生成月度经营报告。</p><p>比如，存款余额、贷款余额、新增客户数、活跃客户数、手机银行 MAU 等核心指标，Agent自动计算同比环比，生成可视化图表，输出报告文本。</p><p>报告初稿生成后，业务人员审核和补充，形成最终的月报。</p><p>第二步：异动指标归因</p><p>在月报中，发现“存款余额”环比下滑 10%，需要进行归因分析。</p><p>分析 Agent 自动进行多维度归因，从时间维度看，是哪几天下滑明显？从地域维度看，是哪些分行下滑？从产品维度看，是哪些存款产品下滑？从客群维度看，是哪些客户群体下滑？</p><p>通过多维度拆解，发现主要是高净值客户的定期存款下滑明显。</p><p>第三步：策略洞察与建议</p><p>基于归因结果，分析 Agent 调用知识库，给出策略建议。</p><p>它调用的是外部通用知识，包括宏观市场环境，比如央行是否调整了利率？市场利率水平如何？以及竞品动态，比如其他银行是否推出了更高收益的产品？</p><p>结合这些外部知识，Agent 给出初步建议，高净值客户可能转向了收益更高的理财产品，建议推出针对性的挽留策略。</p><p>第四步：策略方案设计</p><p>由运营 Agent 调用知识库，设计具体的策略方案。</p><p>它调用的是行业场景级知识，比如针对高净值客户流失的挽留模板、存款产品的营销策略、客户分层运营的方法论等。</p><p>基于这些知识，Agent 生成一个策略方案，筛选出近期存款余额下降的高净值客户，通过客户经理一对一沟通，了解客户需求，推荐适合的理财组合产品。</p><p>同时，Agent 自动生成可执行的流程画布，包括目标人群筛选、触达渠道、沟通话术、跟进流程等。</p><p>第五步：策略动态调优</p><p>运营 Agent 继续调用知识库，对策略进行个性化调优。</p><p>它调用的是企业专属知识，比如本行定义的高净值客群标准、在售的理财产品列表、客户的历史偏好数据、客户经理的能力标签等。</p><p>基于这些企业专属知识，Agent 对策略进行适配，将“高净值客户”的筛选条件调整为本行的定义，将推荐的产品限定为本行在售的产品，将客户分配给合适的客户经理。</p><p>第六步：效果仿真预测与执行</p><p>在策略上线前，运营 Agent 进行效果仿真预测。</p><p>它基于历史数据和模型，模拟用户的反应，预测成功率。比如，预计触达 500 个客户、沟通成功率 60%、最终转化率 30%、挽回存款金额 5000 万。</p><p>业务人员审核预测结果，确认后上线执行。</p><p>执行过程中，实时数据回流，Agent 持续监控效果，如果发现实际效果偏离预测，及时预警，并给出调整建议。</p><p>最终，策略效果数据形成闭环，回流到知识库，用于后续策略的优化和迭代。</p><h3 id="关键认知和体会" tabindex="-1">关键认知和体会 <a class="header-anchor" href="#关键认知和体会" aria-label="Permalink to &quot;关键认知和体会&quot;">​</a></h3><p>从这个案例中，我们可以看到几个关键点。</p><p>第一，知识在不同层级的调用。从外部通用知识，到行业场景级知识，再到企业专属知识，层层深入，让策略越来越精准、越来越适配。</p><p>第二，分析 Agent 与运营 Agent 的协同。分析 Agent 负责发现问题、归因分析、给出建议。运营 Agent 负责策略设计、流程编排、效果预测。两者配合，形成从洞察到行动的完整链路。</p><p>第三则是知识的闭环迭代。策略执行后的效果数据，回流到知识库，不断优化策略模板和知识内容，让 Agent 越来越聪明。</p><h2 id="data-agent-带来的变革可能性" tabindex="-1">Data Agent 带来的变革可能性 <a class="header-anchor" href="#data-agent-带来的变革可能性" aria-label="Permalink to &quot;Data Agent 带来的变革可能性&quot;">​</a></h2><p>通过前面的讨论，我们可以看到，Data Agent 不只是一个工具，而是有可能带来深刻的变革。</p><p>决策智能化</p><p>传统的数据系统，提供的是工具和数据。用户看到数据，理解数据，然后自己做决策。</p><p>而 Data Agent，不仅提供数据和洞察，更能辅助甚至自动执行决策。</p><p>比如，发现某个指标异动，Agent 不只是告诉你“下降了 10%”，还会告诉你“主要原因是高净值客户流失”，并且给出“建议执行挽留策略”，甚至直接生成策略方案，供你审核执行。</p><p>这是从“看数据”到“做决策”的跃迁。</p><p>效果可归因</p><p>传统的企业服务或者内部工具，很难量化效果。买了一套产品，研发了一套系统，到底带来了多少价值？很难说清楚。</p><p>而基于 Data Agent 的服务，由于策略是 Agent 生成的，执行过程是 Agent 监控的，效果数据是实时回流的，就可以实现精细的归因。</p><p>这个策略到底带来了多少转化？贡献了多少收入？ROI 是多少？都可以清晰量化。</p><p>这是从“说不清”到“可量化”的转变。</p><p>持续优化闭环传统的系统，是一次性交付的。交付后，客户自己运营，效果好坏，主要靠客户自己的能力。</p><p>而基于 Agent 的系统，可以形成持续优化的闭环。每一次策略执行，都会产生数据。数据分析后，更新知识库。知识库更新后，Agent 的能力就提升了。</p><p>这样，Agent 在快速反馈中不断迭代，能力持续提升。</p><p>这是一个 L4 级 Agent 的愿景：从分析、决策到执行的全闭环，AI 持续进化。</p><p>商业模式变革</p><p>这些变革，最终也会带来商业模式的变化。关于这个话题，我们在下一节课会专门深入讨论。</p><h2 id="课程总结" tabindex="-1">课程总结 <a class="header-anchor" href="#课程总结" aria-label="Permalink to &quot;课程总结&quot;">​</a></h2><p>今天这节课，我们讨论了关于 Data Agent 的不同观点，以及介绍了如何基于知识库构建 DataAgent。</p><p>对于数据开发工程师，希望这节课能帮你理解，Data Agent 不只是 Text-to-SQL，而是知识驱动的智能体。需要掌握知识库的一个典型架构设计方案，了解 Workflow Agent 和 AgenticAgent 的选择权衡，认识到语义层和指标平台对准确率的关键作用。</p><p>对于数据产品经理，希望这节课能帮你理解 Data Agent 的不同定位及其商业价值，掌握知识分层体系，了解 GUI 加 Chatbox 结合的交互设计思路，认识到从“卖能力”到“卖确定性”的产品设计方向。</p><p>对于数据分析师，希望这节课能帮你理解，Data Agent 是你的得力助手而非替代者，掌握如何利用 Agent 提升日常工作效率，了解指标异动分析、经营报告生成等典型应用场景，认识到知识沉淀和复用的重要性。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ul><li><p>在你的业务中，有碰到交付产品到交付效果的鸿沟吗？你们是怎么解决的？</p></li><li><p>你觉得 Data Agent 更像是降低门槛的工具，还是提效工具？为什么？你认为还有第三种可能性吗？</p></li><li><p>文中提到 GUI 加 Chatbox 的结合，你在实际使用 AI 产品时，更倾向于纯对话交互，还是传统界面加对话辅助？为什么？</p></li></ul><p>期待你在留言区分享你的思考，如果这节课对你有帮助，也欢迎你分享给其他人。下节课，我们将讨论从工具到效果，大模型可能带来的商业模式变革。</p>',182)])])}const c=t(l,[["render",i]]);export{u as __pageData,c as default};
